"""
Parameter
"""
import json
import re
from builtins import str
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
from taf.ul.trs_e2e_fw.lib.oam.admin.parameter_mapper import ParameterMapper
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.exceptions import ParamValueMismatchException, ParamMismatchException, OperatorUnsupportedException

logger = BackgroundLogger.Instance()


class Parameters(AdminBaseClass):
    """
    Parameter
    """
    def __init__(self):
        super(Parameters, self).__init__()
        self.parameter_mapper = ParameterMapper()

    @check_rat
    def get_parameter(self, **kwargs):
        """

        Args:
        rat: RAT of bts
        param_path: string that contains  or partial moc along with the parameters under that moc.
                    full_or_partial_moc:pacompleterameter1:parameter2:parameter3........
        timeout: timeout for query infomodel function of UTE library.
        alias: Execution context.
        str_format: Can be True or False. If True then value of the parmater is returned as a
            string else a dictionary containing mocs, parameters and parameter's value.

        Fucntion performs the following steps:
            1)Validates the RAT type given.
            2)searches full moc name in scf for a given partial moc and gets its parameter's value
                from bts

        Returns: Either a string containing parameter value or a dictionary containing moc as key
            and its value a dictionary of parameters and values .

        """
        param_path = kwargs.get('param_path', '')
        timeout = kwargs.get('timeout', 30)
        alias = kwargs.get('alias', 'default')
        str_format = kwargs.get('str_format', True)
        return self._search_scf_and_get_parameter(param_path=param_path, timeout=timeout,
                                                  alias=alias, str_format=str_format)

    def _search_scf_and_get_parameter(self, param_path='', timeout=30, alias='default',
                                      str_format=True):
        """

        Args:
            param_path: string that contains complete or partial moc along with the parameters
                under that moc. full_or_partial_moc:parameter1:parameter2:parameter3........
            timeout: timeout for query infomodel function of UTE library.
            alias: Execution context.
            str_format: Can be True or False. If True then value of the parameter is returned as
                a string else a dictionary containing mocs, parameters and parameter's value.

        Function performs the following steps:
            1)Get full distnames from the scf if partial moc is given and list of parameters.
            2)get the result dictionary containing all the mocs, their respective parameters, and
                the last parameter's value.
            3)if string format variable is True then get the value of last parameter in the
                parameter's list and return
            it else return the result dictionary obtained in the previous step.


        Returns: Either a string containing parameter value or a dictionary

        """
        logger.debug("Searching dist name for scf and getting parameter")
        dist_regx, param_list = self._get_dist_name_regx_and_parameters_list_from_param_path(
            param_path)
        dist_regx = self.distnames.format_to_infomodel_compatible_distname(dist_regx)
        # dist_name_list, moc_filter, param_list = self._get_dist_name_list_and_paramters_list(
        # param_path, alias)
        # param_value_dict = self._get_param_values_for_all_dists(dist_name_list, param_list,
        # timeout, alias)
        list_of_param_dicts = self.factory.admin_infomodel.query_infomodel(
            "get list {}".format(dist_regx), timeout=timeout, alias=alias, extend_result=False,
            allow_negative_result=False)
        # param_dict = self._get_dict_for_dist_name_from_infomodel(dist_name, timeout, alias)
        distname_paramvalue_dict = {}
        output_parameter_dict = {}
        for param_dict in list_of_param_dicts:
            dist_name = param_dict['dist_name']
            pattern = re.compile(r'_[RL]-\d+')
            if re.search("SCF-\d+/MRBTS_A-\d+", dist_name) or re.search(pattern, dist_name):
                distname_paramvalue_dict[dist_name] = self._get_param_value_by_traversing(
                    param_dict, param_list, timeout, alias)
            else:
                logger.info("Distname {} is WITHOUT MRBTS_A-(btsid). IGNORED IT".format(dist_name))

        if AdminBaseClass.PARAM_VALUE_MAPPING_DATA is not None:
            output_parameter_dict.update(distname_paramvalue_dict)
            logger.debug("output parameter dict :{}".format(output_parameter_dict))
            distname_paramvalue_dict = dict()
            distname_paramvalue_dict = self.parameter_mapper.output_query_infomodel_dict_map_get_param(output_parameter_dict)

        logger.info("Resulting dictionary...\n{}".format(json.dumps(distname_paramvalue_dict,
                                                                    indent=4, sort_keys=True)))
        logger.info('distname_paramvalue_dict: {}'.format(str(distname_paramvalue_dict)))
        return self._convert_dict_to_string(distname_paramvalue_dict, str_format)

    def _verify_dist_name_list_is_empty(self, dist_name_list):
        """

        Args:
            dist_name_list: list of distnames

        Function raises Exception if list of distnames is empty.

        Returns: None

        """
        if len(dist_name_list) == 0:
            BuiltIn().fail("Dist name list is empty. No dist name obtained from dist_regex")

    def _get_dist_name_regx_and_parameters_list_from_param_path(self, param_path):
        """

        Args:
            param_path: string that contains complete or partial moc along with the parameters
                under that moc. full_or_partial_moc:parameter1:parameter2:parameter3........

        Function splits param_path to a list containing distname's regular expression and all
        the parameters.

        Returns: string containing regular expression of distname and list of parameters.

        """
        logger.debug("Fetching dist_name_regx and parameters list....")
        param_path = param_path.split(":")
        logger.debug("dist regx :: {0}\nparam_list :: {1}".format(param_path[0],
                                                                  str(param_path[1:])))
        return param_path[0], param_path[1:]

    def _get_param_values_for_all_dists(self, dist_name_list, param_list, timeout, alias):
        """

        Args:
            dist_name_list: list containing all the distnames that matched with the given distname
                regular expression.
            param_list: list of parameters.
            timeout: timeout for query infomodel function of UTE library.
            alias: Execution context.

        Function to obtain a dictionary containing a MOC's parameters and its values.

        Returns: Nested dictionary containing distname(MOC) as its keys and dictionary of
            respective parameters and its values as their value.

        """
        logger.debug("Getting parameters value for dist list :: {}....".format(
            str(dist_name_list)))
        parameter_value = dict()
        logger.debug("*" * 120)
        for dist_name in dist_name_list:
            parameter_value[dist_name] = self._get_param_values_for_each_dists(dist_name,
                                                                               param_list,
                                                                               timeout, alias)
            logger.debug("*" * 120)
        return parameter_value

    def _get_param_values_for_each_dists(self, dist_name, param_list, timeout, alias):
        """

        Args:
            dist_name: Distname or MOC name
            param_list: List of parameters that are under the given MOC or under the MOC obtained
                from the DN.
            timeout: timeout for query infomodel function of UTE library.
            alias: Execution Context.

        Returns: Dictionary containg whose keys are Distname(MOC) and values are nested
            dictionaries containing parameters and its values

        """
        logger.debug("Getting param values {0} for dist :: {1}".format(str(param_list), dist_name))
        param_dict = self._get_dict_for_dist_name_from_infomodel(dist_name, timeout, alias)
        return self._get_param_value_by_traversing(param_dict, param_list, timeout, alias)

    def _get_param_value_by_traversing(self, param_val, param_list, timeout, alias):
        """

        Args:
            param_val: Dictionary containing a distname's parameter and its values.
            param_list: list of parameters which are to be fetched from the param_value.
            timeout: timeout value for query_infomodel.
            alias: Execution context.

        This function is a recursive function that performs the  following steps.
            1)Function checks if param_list and param_val are not empty(None). This is the base
                condition for the recursive function.
            2)Under the base condition, if param_value is dict
                a. then the param_list[0] is treated as its key and it's
                respective value is fetched.
                b. param_list[0] is removed from the list.
                c. the function calls itself with the result obtained in step 2.a as param_value,
                    list obtained in step 2.b as new param_list and with same timeout and
                    alias value.
            3)Under the base condition, if param_value is a list
                a. the first element of the list which is a dict is taken
                b. then the param_list[0] is treated as the key of the dict obtained in step 3.a
                    and it's respective value is fetched.
                c. param_list[0] is removed from the list.
                d. the function calls itself with the result obtained in step 3.b as param_value,
                    list obtained in step 3.c as new param_list and with same timeout and
                    alias value.
            4)Under the base condition, if param_value is a string
                a. if the string in param_value starts with MRBTS then its complete MOC name is
                    found from scf file present in lmp.
                The param_value then gets the complete MOC name as its value. Next,
                    _get_param_values_for_each_dists is called with its required arguments, which
                    in turn calls  _get_param_value_by_traversing.
                b. if the string in param_value starts with /MRBTS then
                    get_param_values_for_each_dists is called with its required arguments, which
                    in turn calls  _get_param_value_by_traversing.
            5)If the base condition does not satisfy, then the param_value is returned as it is.


        Returns: nested dictionaries containing parameters and its values

        """
        result = dict()
        logger.debug("param_list :: {0}\n param_val ::{1}".format(str(param_list), str(param_val)))
        if param_list and param_val:
            if isinstance(param_val, dict):
                result[param_list[0]] = self._get_param_value_by_traversing(
                    param_val.get(param_list[0]), param_list[1:], timeout, alias)
                logger.debug('result: {}'.format(result))
            elif isinstance(param_val, list):
                result[param_list[0]] = self._get_param_value_by_traversing(
                    param_val[0].get(param_list[0]), param_list[1:], timeout, alias)
            elif str(param_val).startswith('MRBTS-') or str(param_val).startswith('/MRBTS-'):
                if str(param_val).startswith('MRBTS-'):
                    param_val = self.distnames.get_full_distname_from_scf(param_val)
                return self._get_param_values_for_each_dists(param_val, param_list, timeout, alias)
            logger.debug('result_dict: {}'.format(str(result)))
            return result
        return param_val

    def _convert_dict_to_string(self, param_value_dict, str_format):
        """
        Args:
        param_value_dict: Result dictionary obtained from function
            _get_param_values_for_all_dists
        str_format:  Can be True or False. If True then value of the parmater is returned as a
            string else a dictionary containing mocs, parameters and parameter's value.

        Returns:  string value of last parameter in the parameter list or the original
            param_value_dict

        """
        if str_format:
            result_str_value = self._get_string_value_of_result_dict(param_value_dict)
            if result_str_value is not None:
                return result_str_value
            logger.warn("Result dictionary has 0 or many keys. Returning dictionary")
        return param_value_dict

    def _get_string_value_of_result_dict(self, param_value_dict):
        """
        Args:
        param_value_dict: Result dictionary obtained from function _get_param_values_for_all_dists

        Function navigates through the nested dictionary. It finds the innermost key's
        ( last parameter in parameters list ) and returns its value

        Returns: None or value of last parameter in the parameters list.
        """
        while isinstance(param_value_dict, dict):
            if len(param_value_dict) == 1:
                key = list(param_value_dict.keys())[0]
                param_value_dict = param_value_dict[key]
            else:
                return None
        else:
            return param_value_dict

    def _get_dict_for_distname_from_admin(self, dist_name, timeout, alias, err):
        not_full_moc_chars = ["//","*","[","]"]
        for char in not_full_moc_chars:
            if char not in dist_name:
                full_moc_flag = True
                continue
            else:
                full_moc_flag = False
                break
        if full_moc_flag:
            result_dict = self.factory.admin.get_parameters(dist_name=dist_name,timeout=timeout, alias=alias)
            logger.info("Result from get parameters api for distname is : {}".format(dist_name, result_dict))
            result_dict['dist_name'] = dist_name
            return result_dict
        else:
            logger.info("Cannot use admin query as it is not a full MOC!! Hence raising error!!")
            raise err

    def _get_dict_for_dist_name_from_infomodel(self, dist_name, timeout, alias):
        """
        Args:
        dist_name: dsit name or MOC
        timeout: timeout value for query infomodel of UTE's library
        alias: Execution context.

        Function performs the following steps:
        1)calls query_infomodel function of ute_admin_infomodel class, which belongs to UTE
            library. (NOTE:In general, query_infomodel takes distname or MOC regular expression
            and provides list of dictionaries where each dictionary belongs to a matching MOC.
            Here a particular distname is given as an input to query_infomodel function,
            hence we get a list containing only one dictionary.)
        2)Validate if the outpt of query infomodel is right.
        3)return only the dictionary in the list, which is obtained from query infomodel.

        Returns: dictionary containing given distname's parameter and its values.

        """
        try:
            list_of_dicts = self.factory.admin_infomodel.query_infomodel(
                "get list {}".format(dist_name), timeout=timeout, alias=alias,
                extend_result=False, allow_negative_result=False)
        except Exception as e:
            output_dict = self._get_dict_for_distname_from_admin(dist_name, timeout, alias, e)
            list_of_dicts = [output_dict]
        logger.debug("Resulting list of dict :: \n{}".format(json.dumps(list_of_dicts,
                                                                        indent=4,
                                                                        sort_keys=True)))
        if not self._is_list_of_dict_valid(list_of_dicts):
            BuiltIn().fail("Dict for dist name {} is not valid. Unexpected behavior".format(
                dist_name))
        return list_of_dicts[0]

    def _is_list_of_dict_valid(self, list_of_dicts):
        """
        Args:
            list_of_dicts: Output of query infomodel.

        Function verifies if list_of_dicts has only one dictionary in it. If true then Boolean
            True is returned else False is returned.

        Returns: Boolean True or False.
        """
        if len(list_of_dicts) == 0:
            logger.error("Empty list obtained from infomodel")
            return False
        elif len(list_of_dicts) > 1:
            logger.error("List from infomodel contains many dicts")
            return False
        return True

    def _query_from_infomodel_and_get_parameter(self, param_path='', api_version="v1",
                                                timeout=30, extend_result=False,
                                                alias='default', allow_negative_result=False,
                                                str_format=True):
        """
        Args:
        param_path: string that contains  or partial moc along with the parameters under that moc.
                    full_or_partial_moc:pacompleterameter1:parameter2:parameter3........
        api_version: Query api version. Currently available api version is 'v1'
        timeout: Time to wait for possitive query result. After that query will throw
            InfoModelQueryTimeoutException.
        extend_result: Extend result with additional data like query data timestamp.
        alias: Execution context
        allow_negative_result: Allow negative query result to be returned instead of
            InfoModelQueryTimeoutException.
        str_format: Can be True or False. If True then value of the parmater is returned as a
            string else a dictionary containing mocs, parameters and parameter's value.

        Returns: Either a string containing parameter value or a dictionary containing moc as key
            and its value a dictionary of parameters and values .
        """
        logger.debug("Querying infomodel....")
        dist_regx, parameter_list = self._get_dist_name_regx_and_parameters_list_from_param_path(
            param_path)
        param_dict = self._get_param_dict_for_dist_regx(dist_regx, timeout, alias,
                                                        api_version=api_version,
                                                        extend_result=extend_result,
                                                        allow_negative_result=allow_negative_result)
        result_dict = {
            dist_name: self._get_param_value_by_traversing(param_val=param_dict[dist_name],
                                                           param_list=parameter_list,
                                                           timeout=timeout,
                                                           alias=alias)
            for dist_name in param_dict}

        if AdminBaseClass.PARAM_VALUE_MAPPING_DATA is not None:
            result_dict = self.parameter_mapper.output_query_infomodel_dict_map_get_param(result_dict)

        logger.debug("resulting dictionary obtained is \n{}".format(json.dumps(result_dict,
                                                                               indent=4,
                                                                               sort_keys=4)))
        return self._convert_dict_to_string(result_dict, str_format)

    def _get_param_dict_for_dist_regx(self, dist_regx, timeout, alias, api_version, extend_result,
                                      allow_negative_result):
        """
        Args:
        dist_regx: regular expression for distname.
        timeout: Time to wait for possitive query result. After that query will throw
            InfoModelQueryTimeoutException.
        alias: Execution context
        api_version: Query api version. Currently available api version is 'v1'
        extend_result: Extend result with additional data like query data timestamp.
        allow_negative_result: Allow negative query result to be returned instead of
            InfoModelQueryTimeoutException.

        Returns: A dictionary containing moc as key and its value is a dictionary of parameters
            and values .

        """
        try:
            list_of_dicts = self.factory.admin_infomodel.query_infomodel(
                "get list {}".format(dist_regx), timeout=timeout, alias=alias,
                api_version=api_version, extend_result=extend_result,
                allow_negative_result=allow_negative_result)
        except Exception as e:
            output_dict = self._get_dict_for_distname_from_admin(dist_regx, timeout, alias, e)
            list_of_dicts = [output_dict]
        logger.debug("Resulting list of dict :: \n{}".format(json.dumps(list_of_dicts,
                                                                        indent=4,
                                                                        sort_keys=True)))
        return {dist_param_dict["dist_name"]: dist_param_dict for dist_param_dict in list_of_dicts}

    def _verify_parameters_from_result_list_of_dicts(self, result, parameter_list, err):
        result_dict = {}
        verify_param_value = False
        seperator = ['>=', '<=', '!=','=', '>', '<']
        logger.info("Query Response from admin get parameters is : {}".format(result))
        for param in parameter_list:
            for sep in seperator:
                if sep in param.strip():
                    param = param.split(sep)
                    result_dict[param[0].strip()] = {'operator' : sep, 'value' : param[1].strip()}
                    break

        for key, value in result_dict.items():
            if key in result:
                if value['operator'] == '=':
                    if result[key] == value['value']:
                        verify_param_value=True
                    else:
                        verify_param_value = False
                        logger.error("Parameter : {} does not match value {}".format(key, value['value']))
                else:
                    raise OperatorUnsupportedException(
                        """Operator Unsupported Exception in taf admin. Currently supported operator in admin is '='.\nQuery infomodel also failed due to : {}""".format(err))
            else:
                raise ParamMismatchException(
                            "Parameter Mismatch Exception in taf admin.\nQuery infomodel also failed due to : {}".format(err))

        return verify_param_value

    @check_rat
    def query_admin_infomodel(self, **kwargs):
        """

        Args:
        query: Query expression on InfoModel.
        api_version: Query api version. Currently available api version is 'v1'
        timeout: Time to wait for possitive query result. After that query will throw
            InfoModelQueryTimeoutException.
        alias: Execution context
        extend_result: Extend result with additional data like query data timestamp.
        allow_negative_result: Allow negative query result to be returned instead of
            InfoModelQueryTimeoutException.
        **kwargs:kwargs contains str_format. str_format =>  Can be True or False. If True then
            value of the parmater is returned as a string else a dictionary containing mocs,
            parameters and parameter's value.

        Function is wrapper for query_infomodel function od ute_admin_infomodel class of UTE's
            library.
        =>For more details on query_infomodel, follow the website:
        http://doc.ute.inside.nsn.com/packages/ute_admin_infomodel/interfaces/ute_admin_infomodel.html#query-infomodel

        =>This functino also provides a query "get param" in addition to those provided by
        query_infomodel.
        This query is used to get a parameter under a MOC(distname)from bts
        The query is of the type :
            get param DIST_NAME:PARAMETER1:PARAMETER2:PARAMETER3
            If value of PARAMETER1 for DIST_NAME contains a dictionary, then PARAMETER2 is
                fetched from it. Similarly, PARAMETER3 is fetched if value of PARAMETER2 is a
                dictionary.
        *NOTE : If query infomodel fails taf.sbts.oam.coam.admin get_parameters is called as a workaround.
                This alternate call supports only get_list and get_object with "=" as operation for parameters.*

        =>The function performs the following task:
        * If query contains "get param" then function  "_query_from_infomodel_and_get_parameter"
            is called.
        * For other queries, query_infomodel of ute_admin_infomodel class is called.

        Returns: boolean, integer or list

        """
        query = kwargs.get("query")
        api_version = kwargs.get("api_version", "v1")
        timeout = kwargs.get("timeout", 10)
        alias = kwargs.get("alias", "default")
        extend_result = kwargs.get("extend_result", False)
        allow_negative_result = kwargs.get("allow_negative_result", False)

        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["query", "api_version", "timeout", "alias", "extend_result",
                              "allow_negative_result"]}

        if "get param" in query:
            return self._query_from_infomodel_and_get_parameter(
                param_path=query.replace("get param", "").strip(),
                api_version=api_version, timeout=timeout, alias=alias,
                extend_result=extend_result,
                allow_negative_result=allow_negative_result,
                str_format=kwargs.get("str_format", True))

        try:
            if AdminBaseClass.PARAM_VALUE_MAPPING_DATA is not None and "get object" in query and " is " in query:
                query = self.parameter_mapper.input_infomodel_query_map(query)
                logger.debug("query after input map:{}".format(query))

                output_infomodel_dict = self.factory.admin_infomodel.query_infomodel(
                    query, api_version=api_version, timeout=timeout,
                    alias=alias, extend_result=extend_result,
                    allow_negative_result=allow_negative_result)
                logger.debug("output infomodel dict is :{}".format(output_infomodel_dict))
                return self.parameter_mapper.output_query_infomodel_dict_map(output_infomodel_dict)
            else:
                return self.factory.admin_infomodel.query_infomodel(query, api_version=api_version,timeout=timeout,
                                                                    alias=alias, extend_result=extend_result,
                                                                    allow_negative_result=allow_negative_result)

        except Exception as e:
            if "get list" in query:
                query_option ="get list"
                param_path = query.replace("get list", "").strip()
            elif "get object" in query:
                query_option ="get object"
                param_path = query.replace("get object", "").strip()
            else:
                raise e
            param_path = param_path.split(' is ')
            if param_path:
                distname = param_path[0].strip()
            result = self._get_dict_for_distname_from_admin(distname, timeout, alias, e)
            if result:
                if param_path and len(param_path) > 1:
                    parameter_list = param_path[1].strip().strip('[').strip(']').split(",")
                    verify_status = self._verify_parameters_from_result_list_of_dicts(result, parameter_list, e)
                    if not verify_status:
                        raise ParamValueMismatchException(
                            "Parameter Mismatch Exception in taf admin.\nQuery infomodel also failed due to : {}".format(e))
                    else:
                        if query_option == "get list":
                            return [result]
                        else:
                            if AdminBaseClass.PARAM_VALUE_MAPPING_DATA is not None:
                                return self.parameter_mapper.output_query_infomodel_dict_map(result)
                            else:
                                return result
                else:
                    if query_option == "get list":
                        return [result]
                    else:
                        if AdminBaseClass.PARAM_VALUE_MAPPING_DATA is not None:
                            return self.parameter_mapper.output_query_infomodel_dict_map(result)
                        else:
                            return result

    def get_cells_statuses(self, **kwargs):
        """
        Args:
        rat: RAT of bts
        timeout: timeout for query infomodel function of UTE library.
        alias: Execution context.

        Fucntion performs the following steps:
            1)Validates the RAT type given.
            2)searches full moc name in scf for a given partial moc and gets its parameter's value
                from bts

        Returns: Either a string containing parameter value or a dictionary containing mocs,
            parameters and parameter's value.

        """
        timeout = kwargs.get('timeout', 10)
        alias = kwargs.get('alias', 'default')
        param_path = kwargs.get('param_path', '')
        class_name,value = param_path.split(':')
        class_name,id = class_name.split('-')
        result = self.factory.admin.get_parameters_for_all(class_name=class_name, timeout=timeout, connection=alias)
        for res in result:
            if res['id'].split('-')[-1] == id:
                return res[value]